-- Seed all US universities as campuses with coordinates
-- Run with: sudo -u postgres psql -d campuscuts -f seed_campuses.sql

-- First, ensure lat/lng columns exist
ALTER TABLE campuses ADD COLUMN IF NOT EXISTS latitude DECIMAL(10, 6);
ALTER TABLE campuses ADD COLUMN IF NOT EXISTS longitude DECIMAL(10, 6);
CREATE INDEX IF NOT EXISTS idx_campuses_coordinates ON campuses(latitude, longitude);

-- Delete invalid entries
DELETE FROM campuses WHERE name IN ('GMAIL', 'ICLOUD');

-- Insert all universities with coordinates (ON CONFLICT DO UPDATE to add coordinates to existing)
ON CONFLICT (slug) DO UPDATE SET 
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  "updatedAt" = CURRENT_TIMESTAMP;

-- Show results
SELECT COUNT(*) as total_campuses FROM campuses;
SELECT name, city, state, latitude, longitude FROM campuses WHERE latitude IS NOT NULL ORDER BY state, name LIMIT 20;
